//! Golden byte-parity tests for the timeslice sink.
//!
//! The expected `timeslices.{json,csv}` bytes are generated by driving the real
//! Python serializers (`timeslice_metrics_json_exporter._generate_content` /
//! `timeslice_metrics_csv_exporter._generate_content` via
//! `native_report._project_native_timeslices` → `_legacy_stats` → `to_json_result`)
//! over the same synthetic slice values, then pinned here. The single deviation
//! is the Python JSON's outer `input_config` object, which the native report
//! cannot carry (see the module docs); the pinned JSON is the exact per-slice
//! payload minus that key.

use std::collections::BTreeMap;

use super::*;
use crate::metrics_core::report::{
    MetricEntry, MetricSeries, ReportCounterStats, ReportDistributionStats, ReportTimeslice,
};
use crate::metrics_core::{AccumulatorSummary, NativeReport};

/// Build a distribution stats block with finite values.
fn dist(
    count: usize,
    avg: f64,
    min: f64,
    max: f64,
    std: Option<f64>,
    pcts: &[(&str, f64)],
) -> ReportStats {
    ReportStats::Distribution(ReportDistributionStats {
        count: Some(count),
        avg: Some(ReportValue::Finite(avg)),
        min: Some(ReportValue::Finite(min)),
        max: Some(ReportValue::Finite(max)),
        std: std.map(ReportValue::Finite),
        percentiles: pcts
            .iter()
            .map(|(key, value)| (key.to_string(), ReportValue::Finite(*value)))
            .collect(),
    })
}

/// Build a counter stats block (`total` drives avg/min/max/sum in the compatibility shape).
fn counter(total: f64, rate: f64) -> ReportStats {
    ReportStats::Counter(ReportCounterStats {
        total: ReportValue::Finite(total),
        rate: Some(ReportValue::Finite(rate)),
    })
}

/// Build one timeslice.
fn slice(start_ns: i64, end_ns: i64, complete: bool, stats: ReportStats) -> ReportTimeslice {
    ReportTimeslice {
        start_ns,
        end_ns,
        complete,
        stats,
    }
}

/// Build a single-series metric entry with the given timeslices.
fn entry(
    unit: &str,
    metric_type: &'static str,
    aggregate: ReportStats,
    timeslices: Vec<ReportTimeslice>,
) -> MetricEntry {
    MetricEntry {
        metric_type,
        unit: unit.to_string(),
        group: "default",
        higher_is_better: false,
        series: vec![MetricSeries {
            labels: None,
            endpoint_url: None,
            stats: aggregate,
            timeslices,
        }],
    }
}

/// Two-slice report: slice 0 complete, slice 1 partial, plus an INTERNAL metric
/// (`credit_drop_latency`) that must be filtered out of both exports.
fn two_slice_report() -> NativeReport {
    let mut metrics: BTreeMap<String, MetricEntry> = BTreeMap::new();

    metrics.insert(
        "output_sequence_length".to_string(),
        entry(
            "tokens",
            "distribution",
            dist(10, 128.0, 100.0, 150.0, Some(12.0), &[("p50", 128.0)]),
            vec![
                slice(
                    1000,
                    2000,
                    true,
                    dist(10, 128.0, 100.0, 150.0, Some(12.0), &[("p50", 128.0)]),
                ),
                slice(
                    2000,
                    3000,
                    false,
                    dist(4, 130.0, 110.0, 140.0, Some(8.0), &[("p50", 130.0)]),
                ),
            ],
        ),
    );

    metrics.insert(
        "request_count".to_string(),
        entry(
            "requests",
            "counter",
            counter(14.0, 4.5),
            vec![
                slice(1000, 2000, true, counter(10.0, 5.0)),
                slice(2000, 3000, false, counter(4.0, 4.0)),
            ],
        ),
    );

    metrics.insert(
        "request_latency".to_string(),
        entry(
            "ms",
            "distribution",
            dist(14, 13.0, 8.0, 22.0, Some(3.0), &[]),
            vec![
                slice(
                    1000,
                    2000,
                    true,
                    dist(
                        10,
                        12.5,
                        8.0,
                        20.0,
                        Some(3.25),
                        // Deliberately scrambled input order to prove canonical
                        // p1,p5,p10,p50,p99 output ordering (not BTreeMap lexical).
                        &[
                            ("p99", 20.0),
                            ("p1", 8.0),
                            ("p10", 11.0),
                            ("p5", 9.5),
                            ("p50", 12.0),
                        ],
                    ),
                ),
                slice(
                    2000,
                    3000,
                    false,
                    dist(4, 15.0, 9.0, 22.0, None, &[("p50", 15.0)]),
                ),
            ],
        ),
    );

    // INTERNAL metric: present with timeslices, must never reach either file.
    metrics.insert(
        "credit_drop_latency".to_string(),
        entry(
            "ms",
            "distribution",
            dist(4, 1.0, 1.0, 2.0, None, &[]),
            vec![
                slice(
                    1000,
                    2000,
                    true,
                    dist(3, 1.0, 1.0, 1.0, Some(0.0), &[("p50", 1.0)]),
                ),
                slice(2000, 3000, false, dist(1, 2.0, 2.0, 2.0, None, &[])),
            ],
        ),
    );

    let mut report = NativeReport::new(&AccumulatorSummary::new(), None);
    report.metrics = metrics;
    report
}

